mapper.select:
SELECT a.id, a.name, a.remark, a.frequency, a.execute_time executeTime, a.week_days weekDays, a.month_days monthDays, a.custom_cron customCron, a.execute_type executeType, a.enabled, a.object_id objectId, a.object_key objectKey, a.create_id createId, CONVERT(a.create_time, char) createTime, a.last_update_id lastUpdateId, CONVERT(a.last_update_time, char) lastUpdateTime FROM auto_schedule_task a
AND a.tenant_id = #{tenantId}
AND a.object_id = #{objectId}
AND a.object_key = #{objectKey}
AND a.enabled = #{enabled}
${sqlExtract}
AND a.`name` like '%${keyword}%'
ORDER BY a.create_time DESC
